#[derive(Debug, Clone)]
pub struct WriteArgs {
    pub key: ShelfKey,
    pub band: Band,
    pub unit: UnitRef,
    pub stamp: Stamp,
    pub count: Count,
    pub ratio: Ratio,
    pub note: Option<Note>,
    pub slugs: Vec<Stamp>,
    pub panels: Vec<Panel>,
    pub spare: Option<Panel>,
}

pub fn dispatch_write(
    repo: &mut impl crate::kernel::Repository<Shelf>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    args: WriteArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Shelf> {
    args.key.check_invariants()?;
    if !["gram", "litre"].contains(&args.unit.value.as_str()) {
        return Err(crate::kernel::Refusal::InvariantViolation(
            crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                name: "unit",
                admits: "Vocabulary::Unit",
                admitted: &["gram", "litre"],
                offered: format!("{:?}", args.unit.value).as_str(),
            }
            .render_args(),
        ));
    }
    args.unit.check_invariants()?;
    args.stamp.check_invariants()?;
    args.count.check_invariants()?;
    args.ratio.check_invariants()?;
    if let Some(v) = &args.note {
        v.check_invariants()?;
    }
    for item in &args.slugs {
        item.check_invariants()?;
    }
    for item in &args.panels {
        item.check_invariants()?;
    }
    if let Some(v) = &args.spare {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, SHELF_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                let __hydrate_id: String = args.key.value.to_string();
                if __route.aggregate() != __hydrate_id.as_str() {
                    return Err(crate::kernel::Refusal::TypeMismatch(format!(
                        "Write routes to {:?}, but its identity facts name {:?}",
                        __route.aggregate(),
                        __hydrate_id
                    )));
                }
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Shelf {
                        key: Some(args.key.clone()),
                        band: Some(args.band.clone()),
                        unit: Some(args.unit.clone()),
                        stamp: Some(args.stamp.clone()),
                        count: Some(args.count.clone()),
                        ratio: Some(args.ratio.clone()),
                        note: args.note.clone(),
                        slugs: args.slugs.clone(),
                        panels: args.panels.clone(),
                        spare: args.spare.clone(),
                    }),
                    state_independent: true,
                }
            }
            None => {
                let __hydrate_id: String = args.key.value.to_string();
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Shelf {
                        key: Some(args.key.clone()),
                        band: Some(args.band.clone()),
                        unit: Some(args.unit.clone()),
                        stamp: Some(args.stamp.clone()),
                        count: Some(args.count.clone()),
                        ratio: Some(args.ratio.clone()),
                        note: args.note.clone(),
                        slugs: args.slugs.clone(),
                        panels: args.panels.clone(),
                        spare: args.spare.clone(),
                    }),
                    state_independent: true,
                }
            }
        },
        "Write",
        "AttributeConstraintsFixture::Shelf",
        "Shelf",
        "key.value",
        &with_references,
        &[],
        None,
        |record| {
            record.key = Some(args.key.clone());
            record.band = Some(args.band.clone());
            record.unit = Some(args.unit.clone());
            record.stamp = Some(args.stamp.clone());
            record.count = Some(args.count.clone());
            record.ratio = Some(args.ratio.clone());
            record.note = args.note.clone();
            record.slugs = args.slugs.clone();
            record.panels = args.panels.clone();
            record.spare = args.spare.clone();
            Ok(())
        },
        &[],
        &shelf_invariants(),
        &["ShelfWritten"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

